import { z } from "zod";

export type MediaKeyScope =
  | { kind: "workspace-asset"; workspaceId: string }
  | { kind: "workspace-brand"; workspaceId: string }
  | { kind: "project-cover"; projectId: string };

/** Only keys generated by our storage layer may be resolved through the media API. */
export function parseMediaKeyScope(key: string): MediaKeyScope | null {
  const workspace =
    /^uploads\/workspaces\/([^/]+)\/(assets|generated|thumbnails|avatars|covers)\/[^/]+$/.exec(
      key,
    );
  if (workspace && z.uuid().safeParse(workspace[1]).success) {
    return {
      kind:
        workspace[2] === "avatars" || workspace[2] === "covers"
          ? "workspace-brand"
          : "workspace-asset",
      workspaceId: workspace[1]!,
    };
  }

  const project = /^uploads\/projects\/([^/]+)\/covers\/[^/]+$/.exec(key);
  if (project && z.uuid().safeParse(project[1]).success) {
    return { kind: "project-cover", projectId: project[1]! };
  }

  return null;
}
